-- Additive invoice domain migration, generated by Supabase CLI on 2026-11-17.
-- Scope restricted to public.billing_* tables, functions, triggers and security policies.
-- Applies after existing NEUROKLAST canonical schema; never touches customer orders.

-- ============================================================
-- Billing domain: invoices for services sold by the actual seller.
-- Stripe Managed Payments / merchant-of-record sales remain external.
-- Changes are create-only/idempotent; no destructive migration.
-- ============================================================
CREATE TABLE IF NOT EXISTS public.billing_settings (
  id integer PRIMARY KEY DEFAULT 1 CHECK (id=1),
  seller_name text NOT NULL DEFAULT '',
  seller_street text NOT NULL DEFAULT '',
  seller_postal_code text NOT NULL DEFAULT '',
  seller_city text NOT NULL DEFAULT '',
  seller_country text NOT NULL DEFAULT 'DE',
  seller_tax_id text NOT NULL DEFAULT '',
  seller_email text NOT NULL DEFAULT '',
  seller_phone text NOT NULL DEFAULT '',
  seller_contact_name text NOT NULL DEFAULT '',
  seller_iban text NOT NULL DEFAULT '',
  seller_bic text NOT NULL DEFAULT '',
  tax_mode text NOT NULL DEFAULT 'unverified' CHECK (tax_mode IN ('unverified','small_business','vat_registered')),
  number_prefix text NOT NULL DEFAULT 'RE' CHECK (number_prefix ~ '^[A-Z]{2,8}$'),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.billing_customers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL CHECK (length(trim(name)) > 0),
  email text,
  street text NOT NULL DEFAULT '',
  postal_code text NOT NULL DEFAULT '',
  city text NOT NULL DEFAULT '',
  country text NOT NULL DEFAULT 'DE',
  vat_id text,
  buyer_reference text NOT NULL DEFAULT '',
  contact_name text,
  notes text,
  archived boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.billing_customers ADD COLUMN IF NOT EXISTS buyer_reference text NOT NULL DEFAULT '';
ALTER TABLE public.billing_settings ADD COLUMN IF NOT EXISTS seller_phone text NOT NULL DEFAULT '';
ALTER TABLE public.billing_settings ADD COLUMN IF NOT EXISTS seller_contact_name text NOT NULL DEFAULT '';
CREATE INDEX IF NOT EXISTS billing_customers_name_idx ON public.billing_customers (name);
CREATE TABLE IF NOT EXISTS public.billing_sequences (
  issue_year integer PRIMARY KEY CHECK (issue_year BETWEEN 2000 AND 2200),
  next_value bigint NOT NULL DEFAULT 1 CHECK (next_value BETWEEN 1 AND 1000000),
  confirmed boolean NOT NULL DEFAULT false
);
ALTER TABLE public.billing_sequences ADD COLUMN IF NOT EXISTS confirmed boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS public.billing_invoices (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id uuid REFERENCES public.billing_customers(id) ON DELETE RESTRICT,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','preparing','issued')),
  number text UNIQUE,
  issue_date date NOT NULL DEFAULT CURRENT_DATE,
  service_date date NOT NULL DEFAULT CURRENT_DATE,
  due_date date NOT NULL DEFAULT (CURRENT_DATE + 14),
  currency text NOT NULL DEFAULT 'EUR' CHECK (currency='EUR'),
  seller jsonb NOT NULL DEFAULT '{}'::jsonb,
  recipient jsonb NOT NULL DEFAULT '{}'::jsonb,
  lines jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(lines)='array'),
  tax_mode text NOT NULL DEFAULT 'unverified' CHECK (tax_mode IN ('unverified','small_business','vat_registered')),
  e_invoice_profile text NOT NULL DEFAULT 'none' CHECK (e_invoice_profile IN ('none','xrechnung')),
  buyer_reference text NOT NULL DEFAULT '',
  subtotal_cents bigint NOT NULL DEFAULT 0 CHECK (subtotal_cents >= 0),
  tax_cents bigint NOT NULL DEFAULT 0 CHECK (tax_cents >= 0),
  total_cents bigint NOT NULL DEFAULT 0 CHECK (total_cents >= 0),
  note text NOT NULL DEFAULT '',
  created_by uuid,
  issued_at timestamptz,
  pdf_object_key text,
  fodt_object_key text,
  xrechnung_object_key text,
  document_sha256 jsonb NOT NULL DEFAULT '{}'::jsonb,
  document_error_at timestamptz,
  revision integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT billing_invoice_xrechnung_archive CHECK (status <> 'issued' OR e_invoice_profile <> 'xrechnung' OR xrechnung_object_key IS NOT NULL),
  CONSTRAINT billing_invoice_state CHECK (
    (status='draft' AND number IS NULL AND issued_at IS NULL)
    OR (status='preparing' AND number IS NOT NULL AND issued_at IS NULL)
    OR (status='issued' AND number IS NOT NULL AND issued_at IS NOT NULL
       AND pdf_object_key IS NOT NULL AND fodt_object_key IS NOT NULL)
  )
);
ALTER TABLE public.billing_invoices ADD COLUMN IF NOT EXISTS e_invoice_profile text NOT NULL DEFAULT 'none';
ALTER TABLE public.billing_invoices ADD COLUMN IF NOT EXISTS buyer_reference text NOT NULL DEFAULT '';
ALTER TABLE public.billing_invoices ADD COLUMN IF NOT EXISTS xrechnung_object_key text;
CREATE INDEX IF NOT EXISTS billing_invoices_search_idx ON public.billing_invoices (created_at DESC);
CREATE INDEX IF NOT EXISTS billing_invoices_customer_idx ON public.billing_invoices (customer_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.billing_payments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  idempotency_key uuid NOT NULL DEFAULT gen_random_uuid(),
  invoice_id uuid NOT NULL REFERENCES public.billing_invoices(id) ON DELETE RESTRICT,
  amount_cents bigint NOT NULL CHECK (amount_cents > 0),
  paid_on date NOT NULL,
  reference text NOT NULL DEFAULT '',
  created_by uuid,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.billing_payments ADD COLUMN IF NOT EXISTS idempotency_key uuid NOT NULL DEFAULT gen_random_uuid();
CREATE UNIQUE INDEX IF NOT EXISTS billing_payments_idempotency_idx ON public.billing_payments(idempotency_key);
CREATE INDEX IF NOT EXISTS billing_payments_invoice_idx ON public.billing_payments (invoice_id);
CREATE TABLE IF NOT EXISTS public.billing_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  invoice_id uuid REFERENCES public.billing_invoices(id) ON DELETE RESTRICT,
  customer_id uuid REFERENCES public.billing_customers(id) ON DELETE RESTRICT,
  actor_id uuid,
  operation text NOT NULL,
  details jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS billing_events_invoice_idx ON public.billing_events (invoice_id, created_at DESC);

-- Never mutate any committed document/amount after issuance, including via service role.
CREATE OR REPLACE FUNCTION public.billing_protect_issued() RETURNS trigger
LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
BEGIN
  IF OLD.status = 'issued' AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION 'An issued invoice is immutable; create a correction document';
  END IF;
  IF OLD.status = 'preparing' AND (
    NEW.customer_id IS DISTINCT FROM OLD.customer_id OR NEW.issue_date IS DISTINCT FROM OLD.issue_date
    OR NEW.service_date IS DISTINCT FROM OLD.service_date OR NEW.due_date IS DISTINCT FROM OLD.due_date
    OR NEW.lines IS DISTINCT FROM OLD.lines OR NEW.seller IS DISTINCT FROM OLD.seller
    OR NEW.recipient IS DISTINCT FROM OLD.recipient OR NEW.note IS DISTINCT FROM OLD.note
    OR NEW.tax_mode IS DISTINCT FROM OLD.tax_mode OR NEW.e_invoice_profile IS DISTINCT FROM OLD.e_invoice_profile
    OR NEW.buyer_reference IS DISTINCT FROM OLD.buyer_reference OR NEW.total_cents IS DISTINCT FROM OLD.total_cents
    OR NEW.subtotal_cents IS DISTINCT FROM OLD.subtotal_cents OR NEW.tax_cents IS DISTINCT FROM OLD.tax_cents
    OR NEW.number IS DISTINCT FROM OLD.number
  ) THEN
    RAISE EXCEPTION 'Preparing invoice content is frozen';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS billing_protect_issued_trigger ON public.billing_invoices;
CREATE TRIGGER billing_protect_issued_trigger BEFORE UPDATE ON public.billing_invoices
FOR EACH ROW EXECUTE FUNCTION public.billing_protect_issued();

CREATE OR REPLACE FUNCTION public.billing_prepare_issue(p_id uuid, p_actor uuid)
RETURNS public.billing_invoices LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE
  v public.billing_invoices%ROWTYPE;
  conf public.billing_settings%ROWTYPE;
  counter bigint;
  v_issue_year integer;
  v_confirmed boolean;
BEGIN
  SELECT * INTO v FROM public.billing_invoices WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found'; END IF;
  IF v.status IN ('preparing','issued') THEN RETURN v; END IF;
  IF v.status <> 'draft' THEN RAISE EXCEPTION 'Only a draft can be issued'; END IF;
  SELECT * INTO conf FROM public.billing_settings WHERE id=1;
  IF NOT FOUND OR conf.tax_mode='unverified' OR
     trim(conf.seller_name)='' OR trim(conf.seller_street)='' OR
     trim(conf.seller_postal_code)='' OR trim(conf.seller_city)='' OR
     trim(conf.seller_tax_id)='' THEN
    RAISE EXCEPTION 'Seller identity, address, tax identifier and tax mode must be configured';
  END IF;
  IF v.tax_mode <> conf.tax_mode THEN RAISE EXCEPTION 'Tax setting changed; review the draft'; END IF;
  -- The legal seller identity cannot silently change between preview and issuance.
  IF v.seller IS DISTINCT FROM jsonb_build_object(
      'name',conf.seller_name,'street',conf.seller_street,
      'postal_code',conf.seller_postal_code,'city',conf.seller_city,
      'country',conf.seller_country,'tax_id',conf.seller_tax_id,
      'email',conf.seller_email,'phone',conf.seller_phone,'contact_name',conf.seller_contact_name,
      'iban',conf.seller_iban,'bic',conf.seller_bic
  ) THEN
    RAISE EXCEPTION 'Seller details changed; save and review the draft again';
  END IF;
  IF v.total_cents<=0 OR jsonb_array_length(v.lines)=0 THEN
    RAISE EXCEPTION 'Cannot issue an empty invoice';
  END IF;
  IF nullif(trim(v.recipient->>'name'),'') IS NULL OR
     nullif(trim(v.recipient->>'street'),'') IS NULL OR
     nullif(trim(v.recipient->>'postal_code'),'') IS NULL OR
     nullif(trim(v.recipient->>'city'),'') IS NULL THEN
    RAISE EXCEPTION 'Recipient billing address is incomplete';
  END IF;
  v_issue_year := EXTRACT(YEAR FROM v.issue_date)::integer;
  INSERT INTO public.billing_sequences(issue_year,next_value)
    VALUES(v_issue_year,1) ON CONFLICT(issue_year) DO NOTHING;
  SELECT confirmed INTO v_confirmed FROM public.billing_sequences
    WHERE issue_year=v_issue_year FOR UPDATE;
  IF NOT COALESCE(v_confirmed,false) THEN
    RAISE EXCEPTION 'Confirm the invoice number series and prior external invoices before issuance';
  END IF;
  UPDATE public.billing_sequences SET next_value=next_value+1
    WHERE billing_sequences.issue_year=v_issue_year AND next_value<1000000
    RETURNING next_value-1 INTO counter;
  IF counter IS NULL THEN RAISE EXCEPTION 'Invoice number sequence exhausted'; END IF;
  UPDATE public.billing_invoices SET
    status='preparing',
    number=conf.number_prefix||'-'||v_issue_year||'-'||lpad(counter::text,6,'0'),
    revision=revision+1, updated_at=now()
    WHERE id=p_id RETURNING * INTO v;
  INSERT INTO public.billing_events(invoice_id,actor_id,operation,details)
    VALUES(p_id,p_actor,'invoice_number_reserved',jsonb_build_object('number',v.number));
  RETURN v;
END $$;

DROP FUNCTION IF EXISTS public.billing_finalize_issue(uuid,uuid,text,text,jsonb);
CREATE OR REPLACE FUNCTION public.billing_finalize_issue(
  p_id uuid, p_actor uuid, p_pdf_key text, p_fodt_key text, p_hashes jsonb,
  p_xrechnung_key text DEFAULT NULL
) RETURNS public.billing_invoices LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v public.billing_invoices%ROWTYPE;
BEGIN
  SELECT * INTO v FROM public.billing_invoices WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found'; END IF;
  IF v.status='issued' THEN
    IF v.pdf_object_key=p_pdf_key AND v.fodt_object_key=p_fodt_key
       AND v.xrechnung_object_key IS NOT DISTINCT FROM p_xrechnung_key
       AND v.document_sha256=p_hashes THEN
      RETURN v;
    END IF;
    RAISE EXCEPTION 'Issued document archive cannot be modified';
  END IF;
  IF v.status<>'preparing' THEN RAISE EXCEPTION 'Invoice not preparing'; END IF;
  IF p_pdf_key IS DISTINCT FROM ('billing/'||p_id||'/'||v.number||'.pdf') OR
     p_fodt_key IS DISTINCT FROM ('billing/'||p_id||'/'||v.number||'.fodt') THEN
    RAISE EXCEPTION 'Unexpected document key';
  END IF;
  IF jsonb_typeof(p_hashes) IS DISTINCT FROM 'object'
     OR NOT COALESCE((p_hashes->>'pdf') ~ '^[0-9a-f]{64}$',false)
     OR NOT COALESCE((p_hashes->>'fodt') ~ '^[0-9a-f]{64}$',false)
     OR NOT COALESCE((p_hashes->>'odt') ~ '^[0-9a-f]{64}$',false) THEN
    RAISE EXCEPTION 'PDF, FODT and ODT SHA-256 checksums are required';
  END IF;
  IF v.e_invoice_profile='xrechnung' THEN
    IF p_xrechnung_key IS DISTINCT FROM ('billing/'||p_id||'/'||v.number||'.xml')
       OR NOT COALESCE((p_hashes->>'xrechnung') ~ '^[0-9a-f]{64}$',false) THEN
      RAISE EXCEPTION 'Validated XRechnung XML archive and checksum are required';
    END IF;
  ELSIF p_xrechnung_key IS NOT NULL OR p_hashes ? 'xrechnung' THEN
    RAISE EXCEPTION 'Unexpected electronic invoice for standard document';
  END IF;
  UPDATE public.billing_invoices SET status='issued',issued_at=now(),
    pdf_object_key=p_pdf_key,fodt_object_key=p_fodt_key,
    xrechnung_object_key=p_xrechnung_key,
    document_sha256=p_hashes,document_error_at=NULL,updated_at=now()
    WHERE id=p_id RETURNING * INTO v;
  INSERT INTO public.billing_events(invoice_id,actor_id,operation,details)
    VALUES(p_id,p_actor,'invoice_issued',jsonb_build_object('number',v.number,'hashes',p_hashes));
  RETURN v;
END $$;

DROP FUNCTION IF EXISTS public.billing_record_payment(uuid,uuid,bigint,date,text);
CREATE OR REPLACE FUNCTION public.billing_record_payment(
  p_id uuid, p_actor uuid, p_amount bigint, p_paid_on date, p_reference text,
  p_idempotency_key uuid
) RETURNS public.billing_payments LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v public.billing_invoices%ROWTYPE;
  outstanding bigint; result public.billing_payments%ROWTYPE;
BEGIN
  IF p_idempotency_key IS NULL THEN RAISE EXCEPTION 'Payment request ID required'; END IF;
  SELECT * INTO v FROM public.billing_invoices WHERE id=p_id FOR UPDATE;
  IF NOT FOUND OR v.status<>'issued' THEN RAISE EXCEPTION 'Invoice must be issued'; END IF;
  SELECT * INTO result FROM public.billing_payments WHERE idempotency_key=p_idempotency_key;
  IF FOUND THEN
    IF result.invoice_id=p_id AND result.amount_cents=p_amount
       AND result.paid_on=p_paid_on AND result.reference=left(coalesce(p_reference,''),240) THEN
      RETURN result;
    END IF;
    RAISE EXCEPTION 'Payment request ID already used for another operation';
  END IF;
  SELECT v.total_cents-COALESCE(SUM(amount_cents),0) INTO outstanding
    FROM public.billing_payments WHERE invoice_id=p_id;
  IF p_amount<=0 OR p_amount>outstanding THEN RAISE EXCEPTION 'Invalid payment amount'; END IF;
  INSERT INTO public.billing_payments(invoice_id,amount_cents,paid_on,reference,created_by,idempotency_key)
    VALUES(p_id,p_amount,p_paid_on,left(coalesce(p_reference,''),240),p_actor,p_idempotency_key)
    RETURNING * INTO result;
  INSERT INTO public.billing_events(invoice_id,actor_id,operation,details)
    VALUES(p_id,p_actor,'payment_recorded',jsonb_build_object(
      'payment_id',result.id,'amount_cents',p_amount,'idempotency_key',p_idempotency_key));
  RETURN result;
END $$;

ALTER TABLE public.billing_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.billing_customers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.billing_sequences ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.billing_invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.billing_payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.billing_events ENABLE ROW LEVEL SECURITY;
-- No authenticated/anon policies: all data access is through the authenticated server domain.
REVOKE ALL ON FUNCTION public.billing_prepare_issue(uuid,uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.billing_finalize_issue(uuid,uuid,text,text,jsonb,text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.billing_record_payment(uuid,uuid,bigint,date,text,uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.billing_prepare_issue(uuid,uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.billing_finalize_issue(uuid,uuid,text,text,jsonb,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.billing_record_payment(uuid,uuid,bigint,date,text,uuid) TO service_role;


-- MCP financial requests are separate from editorial approval requests.
CREATE TABLE IF NOT EXISTS public.billing_mcp_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  operation text NOT NULL CHECK (operation IN ('issue_invoice','record_payment')),
  invoice_id uuid NOT NULL REFERENCES public.billing_invoices(id) ON DELETE RESTRICT,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  requested_by uuid NOT NULL,
  client_id text NOT NULL,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','approved','rejected')),
  reviewed_by uuid,
  reviewed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS billing_mcp_review_idx ON public.billing_mcp_requests (status,created_at DESC);
ALTER TABLE public.billing_mcp_requests ENABLE ROW LEVEL SECURITY;
-- Payment and request approval must be committed in ONE PostgreSQL transaction.
CREATE OR REPLACE FUNCTION public.billing_approve_mcp_payment(
  p_request_id uuid, p_actor uuid
) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE req public.billing_mcp_requests%ROWTYPE;
  inv public.billing_invoices%ROWTYPE;
  amount bigint; paid_on date; paid bigint; payment_id uuid;
BEGIN
  SELECT * INTO req FROM public.billing_mcp_requests WHERE id=p_request_id FOR UPDATE;
  IF NOT FOUND OR req.status<>'pending' OR req.operation<>'record_payment' THEN
    RAISE EXCEPTION 'Payment review request unavailable';
  END IF;
  amount := (req.payload->>'amount_cents')::bigint;
  paid_on := (req.payload->>'paid_on')::date;
  SELECT * INTO inv FROM public.billing_invoices WHERE id=req.invoice_id FOR UPDATE;
  IF NOT FOUND OR inv.status<>'issued' THEN RAISE EXCEPTION 'Invoice not issued'; END IF;
  SELECT COALESCE(SUM(amount_cents),0) INTO paid FROM public.billing_payments WHERE invoice_id=inv.id;
  IF amount<=0 OR amount>inv.total_cents-paid THEN RAISE EXCEPTION 'Payment exceeds open balance'; END IF;
  INSERT INTO public.billing_payments(invoice_id,amount_cents,paid_on,reference,created_by)
    VALUES(inv.id,amount,paid_on,left(coalesce(req.payload->>'reference',''),240),p_actor)
    RETURNING id INTO payment_id;
  UPDATE public.billing_mcp_requests SET status='approved',reviewed_by=p_actor,reviewed_at=now() WHERE id=req.id;
  INSERT INTO public.billing_events(invoice_id,actor_id,operation,details)
    VALUES(inv.id,p_actor,'mcp_payment_approved',jsonb_build_object('payment_id',payment_id,'request_id',p_request_id));
  RETURN payment_id;
END $$;
REVOKE ALL ON FUNCTION public.billing_approve_mcp_payment(uuid,uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.billing_approve_mcp_payment(uuid,uuid) TO service_role;


-- One-time sequence alignment for pre-existing externally numbered invoices.
-- Refuses changes as soon as this module has reserved a number in that year.
CREATE OR REPLACE FUNCTION public.billing_seed_sequence(
  p_year integer, p_next bigint, p_actor uuid
) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE current_value bigint; was_confirmed boolean;
BEGIN
  IF p_year<2000 OR p_year>2200 OR p_next<1 OR p_next>999999 THEN
    RAISE EXCEPTION 'Invalid invoice sequence seed';
  END IF;
  INSERT INTO public.billing_sequences(issue_year,next_value)
    VALUES(p_year,1) ON CONFLICT(issue_year) DO NOTHING;
  SELECT next_value,confirmed INTO current_value,was_confirmed FROM public.billing_sequences
    WHERE issue_year=p_year FOR UPDATE;
  IF was_confirmed THEN
    IF current_value=p_next THEN RETURN p_next; END IF;
    RAISE EXCEPTION 'Number series already confirmed; it cannot be reset';
  END IF;
  IF EXISTS(SELECT 1 FROM public.billing_invoices
      WHERE issue_date>=make_date(p_year,1,1)
        AND issue_date<make_date(p_year+1,1,1) AND number IS NOT NULL) THEN
    RAISE EXCEPTION 'This invoice year has already been used; sequence cannot be changed';
  END IF;
  UPDATE public.billing_sequences SET next_value=p_next,confirmed=true WHERE issue_year=p_year;
  INSERT INTO public.billing_events(actor_id,operation,details)
    VALUES(p_actor,'invoice_sequence_seeded',jsonb_build_object('year',p_year,'previous',current_value,'next',p_next));
  RETURN p_next;
END $$;
REVOKE ALL ON FUNCTION public.billing_seed_sequence(integer,bigint,uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.billing_seed_sequence(integer,bigint,uuid) TO service_role;


-- Durable append-only financial records. Corrections must be new linked events.
CREATE OR REPLACE FUNCTION public.billing_prevent_destructive_changes() RETURNS trigger
LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
BEGIN
  IF TG_TABLE_NAME='billing_invoices' THEN
    IF TG_OP='DELETE' AND OLD.status='draft' THEN
      RETURN OLD;
    END IF;
  END IF;
  RAISE EXCEPTION 'Financial records are append-only; use a formally linked correction';
END $$;
DROP TRIGGER IF EXISTS billing_invoice_prevent_delete ON public.billing_invoices;
CREATE TRIGGER billing_invoice_prevent_delete BEFORE DELETE ON public.billing_invoices
FOR EACH ROW EXECUTE FUNCTION public.billing_prevent_destructive_changes();
DROP TRIGGER IF EXISTS billing_payment_prevent_changes ON public.billing_payments;
CREATE TRIGGER billing_payment_prevent_changes BEFORE UPDATE OR DELETE ON public.billing_payments
FOR EACH ROW EXECUTE FUNCTION public.billing_prevent_destructive_changes();
DROP TRIGGER IF EXISTS billing_events_prevent_changes ON public.billing_events;
CREATE TRIGGER billing_events_prevent_changes BEFORE UPDATE OR DELETE ON public.billing_events
FOR EACH ROW EXECUTE FUNCTION public.billing_prevent_destructive_changes();


-- Actor-preserving audit for edits before an invoice is issued.
ALTER TABLE public.billing_settings ADD COLUMN IF NOT EXISTS updated_by uuid;
ALTER TABLE public.billing_customers ADD COLUMN IF NOT EXISTS created_by uuid;
ALTER TABLE public.billing_customers ADD COLUMN IF NOT EXISTS updated_by uuid;
ALTER TABLE public.billing_invoices ADD COLUMN IF NOT EXISTS updated_by uuid;

CREATE OR REPLACE FUNCTION public.billing_audit_edits() RETURNS trigger
LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
BEGIN
  IF TG_TABLE_NAME='billing_customers' THEN
    INSERT INTO public.billing_events(customer_id,actor_id,operation)
    VALUES (NEW.id,NEW.updated_by,CASE WHEN TG_OP='INSERT' THEN 'customer_created' ELSE 'customer_updated' END);
  ELSIF TG_TABLE_NAME='billing_invoices' THEN
    IF NEW.status='draft' THEN
      INSERT INTO public.billing_events(invoice_id,actor_id,operation)
      VALUES (NEW.id,NEW.updated_by,CASE WHEN TG_OP='INSERT' THEN 'draft_created' ELSE 'draft_updated' END);
    END IF;
  ELSIF TG_TABLE_NAME='billing_settings' THEN
    INSERT INTO public.billing_events(actor_id,operation,details)
    VALUES (NEW.updated_by,'seller_settings_updated',jsonb_build_object('tax_mode',NEW.tax_mode));
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS billing_customer_audit ON public.billing_customers;
CREATE TRIGGER billing_customer_audit AFTER INSERT OR UPDATE ON public.billing_customers
FOR EACH ROW EXECUTE FUNCTION public.billing_audit_edits();
DROP TRIGGER IF EXISTS billing_draft_audit ON public.billing_invoices;
CREATE TRIGGER billing_draft_audit AFTER INSERT OR UPDATE ON public.billing_invoices
FOR EACH ROW EXECUTE FUNCTION public.billing_audit_edits();
DROP TRIGGER IF EXISTS billing_settings_audit ON public.billing_settings;
CREATE TRIGGER billing_settings_audit AFTER INSERT OR UPDATE ON public.billing_settings
FOR EACH ROW EXECUTE FUNCTION public.billing_audit_edits();


-- Permission-safe, aggregated payment totals for paginated invoice overviews.
CREATE OR REPLACE VIEW public.billing_invoice_balances
WITH (security_invoker = true) AS
SELECT invoice_id, SUM(amount_cents)::bigint AS paid_cents
FROM public.billing_payments
GROUP BY invoice_id;
REVOKE ALL ON public.billing_invoice_balances FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.billing_invoice_balances TO service_role;
